#pragma once

// CAurCamera is the engine's main camera interface, abstract and vtable-only. Nothing holds one by
// value; callers hold the CAurCamera* the NewCAurCamera(char*) factory hands back.

#include "Vector.h"
#include "Quaternion.h"
#include "Plane.h"
#include "List.h"

class CAurBehavior;
class CAurObject;
class CAurPart;
class CAurScene;
class CHitInfo;
struct Plane;

class CAurCamera {
public:
    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 36 slots
    // The destructor body must be written here rather than only declared: that is what makes the
    // D2/D0 symbols weak. It is also why D0 is a trap instruction, which any abstract class gets.
    virtual ~CAurCamera() {}  // slots 0-1
    virtual CAurObject* AsCAurObject() = 0;
    virtual void RenderScene() = 0;
    virtual void Animate(float a) = 0;
    virtual int  PlayAnimation(const char* a, float b, int c, float d) = 0;
    virtual int  AttachToScene(CAurScene* a) = 0;
    virtual Vector SetPosition(Vector vPos) = 0;
    virtual void SetOrientation(Quaternion a) = 0;
    virtual Vector GetPosition() = 0;
    virtual Quaternion GetOrientation() = 0;
    virtual Vector MapToScreen(Vector, bool) = 0;
    virtual Vector MouseDir(int, int) = 0;  // the caller selects the lane of the returned vector
    virtual int HitCheck(int, int, Vector*, CHitInfo*) = 0;  // returns the scene's hit-check result
    virtual void SetViewPort(int, int, int, int) = 0;
    virtual int  GetViewPortHeight() = 0;
    virtual void GetClipDist(float&, float&) = 0;
    virtual void SetClipDist(float fMin, float fMax) = 0;
    virtual void SetViewAngle(float fAngle) = 0;
    virtual float GetViewAngle() = 0;
    virtual float HitCheckViewVolumeNearest(Vector const&, Vector const&, Vector*, int*) = 0;  // the hit distance, or the far clip
    virtual bool SceneBoundaryCheck(Vector const&, Vector const&, Plane const&, Vector*) = 0;
    virtual void BeginViewAngleAnimation(float, float, int) = 0;
    virtual void EndViewAngleAnimation(bool) = 0;
    virtual void SetFollow(CAurObject*) = 0;
    virtual void BehaviorMessage(char* a) = 0;
    virtual float GetYaw() = 0;
    virtual float GetPitch() = 0;
    virtual float GetDist() = 0;
    virtual void* AsAurCamera() { return this; }
    virtual void* AttachToObject(CAurObject* a, char* b, int c) = 0;
    virtual void* AttachToPart(CAurObject* a, CAurPart* b, int c) = 0;
    virtual void SetBehavior(CAurBehavior* pBehavior) = 0;
    virtual CAurBehavior* GetBehavior(int nBehaviorId) = 0;
    virtual int  ViewVolumeSet() = 0;
    virtual Plane GetViewVolume(int) = 0;
    // </VTABLE-GEN>
};

// Camera is the client camera, created only by the NewCAurCamera(char*) factory. With multiple
// inheritance, CAurCamera is the first base (the primary vtable) and Gob the second (the secondary,
// whose overridden slots become the -8 adjusting thunks). Gob derives CAurObject, so the Gob
// subobject is also the CAurObject subobject and AsCAurObject is a cast to it.
//
// The vtable's slot order must not change. The last eight slots are camera-only new virtuals.
// The camera's own fields extend Gob's.

#ifndef CAMERA_H
#define CAMERA_H

#include "AURORA/aurmodel.h"

class CAurScene;
struct Plane;

class Camera : public CAurCamera, public Gob {
public:

    Camera(char* pszName);

    // Gob's PlayAnimation(char*) and four-argument HitCheck stay callable through a Camera: the
    // camera's own overloads below take other parameter lists.
    using Gob::PlayAnimation;
    using Gob::HitCheck;

    virtual ~Camera();                        // slots 0-1

    // CAurCamera's primary interface, in vtable slot order.
    virtual CAurObject* AsCAurObject() override;
    virtual void RenderScene() override;           // rebuilds the view volume, then draws
    virtual void Animate(float a) override;        // steps the view-angle tween, then Gob::Animate
    virtual int  PlayAnimation(const char* a, float b, int c, float d) override; // always returns 0
    virtual int  AttachToScene(CAurScene* a) override;
    virtual Vector SetPosition(Vector a) override;
    virtual void  SetOrientation(Quaternion a) override;
    virtual Vector GetPosition() override;
    virtual Quaternion GetOrientation() override;
    virtual Vector MapToScreen(Vector, bool) override;
    virtual Vector MouseDir(int, int) override;
    virtual int HitCheck(int, int, Vector*, CHitInfo*) override;
    virtual void SetViewPort(int, int, int, int) override;
    virtual int  GetViewPortHeight() override;
    virtual void GetClipDist(float&, float&) override;
    virtual void SetClipDist(float fMin, float fMax) override;
    virtual void SetViewAngle(float fAngle) override;
    virtual float GetViewAngle() override;
    virtual float HitCheckViewVolumeNearest(Vector const&, Vector const&, Vector*, int*) override; // the hit distance, or the far clip
    virtual bool SceneBoundaryCheck(Vector const&, Vector const&, Plane const&, Vector*) override;
    virtual void BeginViewAngleAnimation(float, float, int) override;
    virtual void EndViewAngleAnimation(bool) override;
    virtual void SetFollow(CAurObject*) override;
    virtual void BehaviorMessage(char* a) override;    // forwards to Gob
    virtual float GetYaw() override;
    virtual float GetPitch() override;
    virtual float GetDist() override;
    // AsAurCamera is inherited unchanged from CAurCamera, so it is not redeclared here.
    virtual void* AttachToObject(CAurObject* a, char* b, int c) override;  // forwards to Gob
    virtual void* AttachToPart(CAurObject* a, CAurPart* b, int c) override; // forwards to Gob
    virtual void SetBehavior(CAurBehavior* pBehavior) override; // forwards to Gob
    virtual CAurBehavior* GetBehavior(int nBehaviorId) override; // forwards to Gob
    virtual int  ViewVolumeSet() override;
    virtual Plane GetViewVolume(int nIndex) override;

    // The camera-only new virtuals, appended to the primary segment in this order.
    virtual CAurCamera* AsCAurCamera() override;
    virtual void Render(bool a) override;
    virtual Vector GetPreviousPosition() override;
    virtual void HitCheck(Vector, Vector, Vector*);  // camera-only overload
    virtual void SetFadePlanes(Plane&, Plane&);
    virtual void* AsCamera() override;
    virtual void GetMinimumBoundingBox(Vector&, Vector&) override;
    virtual void GetMinimumBoundingSphere(Vector&, float&) override;

    // The camera's own fields, after Gob's.
    float  m_fViewAngle;
    void*  m_pViewAnimState;
    float  m_fViewAnimDefault;
    float  m_fClipNear;
    float  m_fClipFar;
    int    m_nViewX;
    int    m_nViewY;
    int    m_nViewW;
    int    m_nViewH;
    int    m_nViewVolumeSet;
    struct ViewState {
        // Six view-frustum planes, near, far, then the four sides.
        List<Plane> m_aViewVolumes;
        float  m_aFadePlane[4];
        Plane  m_fadeNear;
        Plane  m_fadeFar;
    } m_viewState;
};

// AsCAurObject returns this because the CAurObject subobject is the Gob subobject (Gob derives
// CAurObject).
inline CAurObject* Camera::AsCAurObject() { return this; }

// GetPosition and GetOrientation exist only to disambiguate the two base copies.
inline Vector Camera::GetPosition() { return m_vPosition; }

inline Quaternion Camera::GetOrientation() { return m_qOrientation; }

inline int Camera::GetViewPortHeight() { return m_nViewH; }

inline void Camera::GetClipDist(float& fMin, float& fMax)
{
    fMin = m_fClipNear;
    fMax = m_fClipFar;
}

inline float Camera::GetViewAngle() { return m_fViewAngle; }

inline int Camera::ViewVolumeSet() { return m_nViewVolumeSet; }

inline CAurCamera* Camera::AsCAurCamera() { return this; }

inline Vector Camera::GetPreviousPosition() { return m_vPreviousPosition; }

inline void Camera::SetFadePlanes(Plane& pFadeNear, Plane& pFadeFar)
{
    m_viewState.m_fadeNear = pFadeNear;
    m_viewState.m_fadeFar = pFadeFar;
}

inline void* Camera::AsCamera() { return this; }

inline void Camera::GetMinimumBoundingSphere(Vector& a, float& b) { K2_UNUSED(a); K2_UNUSED(b); }

#endif // CAMERA_H
